SELECT 'amazon_daily'::text AS view_name, 'orders'::text AS domain, 'Amazon.com + B2B sales and Amazon Ads (de-duplicated across v1 / v2 / v3 report generations) by purchase day.'::text AS description, 'one row per day'::text AS grain, (SELECT min(day) FROM public.proj_feed_amazon)::date AS first_day, (SELECT max(day) FROM public.proj_feed_amazon)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_amazon')) AS row_estimate
