SELECT 'site_traffic_daily'::text AS view_name, 'orders'::text AS domain, 'Pixel-tracked visitors, new visitors and sessions per day (Upstack).'::text AS description, 'one row per day'::text AS grain, (SELECT min(day) FROM public.proj_feed_traffic)::date AS first_day, (SELECT max(day) FROM public.proj_feed_traffic)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_traffic')) AS row_estimate
