SELECT 'platform_daily_history'::text AS view_name, 'marketing'::text AS domain, 'Meta and Google spend and platform-reported conversions per day from 2025-01-01 (Upstack ad-platform feed): the longest spend history in the database.'::text AS description, 'one row per (day, platform)'::text AS grain, (SELECT min(day) FROM public.proj_feed_platform)::date AS first_day, (SELECT max(day) FROM public.proj_feed_platform)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_platform')) AS row_estimate
