SELECT 'meta_product_daily'::text AS view_name, 'marketing'::text AS domain, 'Meta spend and link clicks per day by product, classified campaign name -> ad set name -> ad name -> Other.'::text AS description, 'one row per (day, product) after the day rule'::text AS grain, (SELECT min(day) FROM public.proj_feed_meta_product)::date AS first_day, (SELECT max(day) FROM public.proj_feed_meta_product)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_meta_product')) AS row_estimate
