COMMENT ON COLUMN analytics.amazon_ads_keywords_snapshot.campaign_id IS 'Campaign id.';
COMMENT ON COLUMN analytics.amazon_ads_keywords_snapshot.keyword_text IS 'Keyword text.';
COMMENT ON COLUMN analytics.amazon_ads_keywords_snapshot.match_type IS 'BROAD | PHRASE | EXACT.';
COMMENT ON COLUMN analytics.amazon_ads_keywords_snapshot.bid IS 'Bid in US dollars at the snapshot.';
